namespace MyApp.Tests;

public sealed class DbFixture : IDisposable
{
    public string Connection { get; } = "memory";
    public void Dispose() { }
}

/// <summary>
/// Shares a single DbFixture instance across test classes that formerly
/// belonged to the xUnit "Db" collection.
/// </summary>
internal static class SharedDbFixture
{
    private static readonly Lazy<DbFixture> s_lazy = new(() => new DbFixture());
    private static int s_refCount;

    public static DbFixture Instance
    {
        get
        {
            Interlocked.Increment(ref s_refCount);
            return s_lazy.Value;
        }
    }

    public static void CleanupIfLast()
    {
        if (Interlocked.Decrement(ref s_refCount) == 0 && s_lazy.IsValueCreated)
            s_lazy.Value.Dispose();
    }
}

